function fmtClimate(v,unit){return (v===null||v===undefined||Number.isNaN(v))?'—':Number(v).toLocaleString('ko-KR',{maximumFractionDigits:1})+unit}
function renderClimate(region){
  const box=$('#climateContent'),d=CLIMATE1991_2020[region.id];
  if(!d){
    box.className='climate-empty';
    box.innerHTML='<b>기후 자료 없음</b><br>해당 지역에 이번 1991~2020 기후평년값 자료의 관측지점이 없습니다.';
    return;
  }
  const summerPct=d.annualP&&d.summerP!=null?d.summerP/d.annualP*100:0;
  const winterPct=d.annualP&&d.winterP!=null?d.winterP/d.annualP*100:0;
  const restPct=Math.max(0,100-summerPct-winterPct);
  box.className='';
  box.innerHTML=`
    <div class="climate-station">대표 관측지점: <b>${d.station}</b> (${d.stationNo})</div>
    <div class="climate-grid">
      <div class="climate-item"><span>1월 평균기온</span><b>${fmtClimate(d.jan,'℃')}</b></div>
      <div class="climate-item"><span>8월 평균기온</span><b>${fmtClimate(d.aug,'℃')}</b></div>
      <div class="climate-item"><span>기온 연교차</span><b>${fmtClimate(d.range,'℃')}</b></div>
      <div class="climate-item"><span>연 강수량</span><b>${fmtClimate(d.annualP,'mm')}</b></div>
      <div class="climate-item"><span>여름 강수량</span><b>${fmtClimate(d.summerP,'mm')}</b></div>
      <div class="climate-item"><span>겨울 강수량</span><b>${fmtClimate(d.winterP,'mm')}</b></div>
    </div>
    <div class="climate-rainbar" aria-label="연강수량 중 여름과 겨울 강수 비중">
      <div class="climate-summer" style="width:${summerPct.toFixed(2)}%"></div>
      <div class="climate-winter" style="width:${winterPct.toFixed(2)}%"></div>
      <div class="climate-rest" style="width:${restPct.toFixed(2)}%"></div>
    </div>
    <div class="climate-legend"><span>여름 ${summerPct.toFixed(1)}%</span><span>겨울 ${winterPct.toFixed(1)}%</span><span>나머지 계절 ${restPct.toFixed(1)}%</span></div>
    <div class="age-note">여름 강수 집중률 ${d.summerShare==null?'—':d.summerShare.toFixed(1)+'%'} · 겨울 강수 집중률 ${d.winterShare==null?'—':d.winterShare.toFixed(1)+'%'}<br>연교차 = 8월 평균기온 − 1월 평균기온</div>`;
}
function fmtPop(n){return n.toLocaleString('ko-KR')+'명'}
function renderPopulation(region){
  const box=$('#populationContent');
  const d=POP2024[region.id];
  if(!d){
    box.className='pop-pending';
    box.innerHTML='이 지역의 인구 자료는 <b>2차 2번 수정</b>에서 추가됩니다.';
    return;
  }
  const mp=d.male/d.total*100, fp=d.female/d.total*100;
  const ratio=d.male/d.female*100;
  box.className='';
  box.innerHTML=`
    <div class="pop-total">${fmtPop(d.total)}</div>
    <div class="sexbar" aria-label="남녀 인구 구성비">
      <div class="sexbar-m" style="width:${mp.toFixed(2)}%"></div>
      <div class="sexbar-f" style="width:${fp.toFixed(2)}%"></div>
    </div>
    <div class="sexlegend"><span>남 ${mp.toFixed(1)}%</span><span>여 ${fp.toFixed(1)}%</span></div>
    <div class="sex-grid">
      <div class="sex-item"><span>남자 인구</span><b>${fmtPop(d.male)}</b></div>
      <div class="sex-item"><span>여자 인구</span><b>${fmtPop(d.female)}</b></div>
    </div>
    <div class="sexratio">성비 <b>${ratio.toFixed(1)}</b><br><span class="small">여자 100명당 남자 수</span></div>`;
  const a=AGE2024[region.id];
  const yp=a.youth/a.total*100, ap=a.adult/a.total*100, op=a.old/a.total*100;
  box.innerHTML+=`<div class="age-section"><div class="age-head">연령별 인구 구조</div><div class="agebar" aria-label="연령별 인구 구성비"><div class="age-y" style="width:${yp.toFixed(2)}%"></div><div class="age-a" style="width:${ap.toFixed(2)}%"></div><div class="age-o" style="width:${op.toFixed(2)}%"></div></div><div class="age-grid"><div class="age-item"><span>유소년층</span><b>${yp.toFixed(1)}%</b><em>${fmtPop(a.youth)}</em></div><div class="age-item"><span>청장년층</span><b>${ap.toFixed(1)}%</b><em>${fmtPop(a.adult)}</em></div><div class="age-item"><span>노년층</span><b>${op.toFixed(1)}%</b><em>${fmtPop(a.old)}</em></div></div><div class="age-note">0~14세 / 15~64세 / 65세 이상 · 2024년 12월 주민등록인구</div></div>`;
}
let selectedStudy=null;
const tabButtons=[...document.querySelectorAll('.nav button[data-tab]')];

const panels = {
  quiz: $('#quizPanel'),
  study: $('#studyPanel'),
  atlas: $('#atlasPanel'),
  ranking: $('#rankingPanel'),
  climateRanking: $('#climateRankingPanel'),
  industry: $('#industryPanel'),
  energy: $('#energyPanel'),
  notes: $('#notesPanel')
};


function openTab(name){
  if(name==='ranking' && typeof renderRanking==='function') renderRanking();
  if(name==='climateRanking' && typeof renderClimateRanking==='function') renderClimateRanking();
  if(name==='industry' && typeof renderIndustryMap==='function') renderIndustryMap();
  Object.entries(panels).forEach(([k,p])=>p.classList.toggle('hidden',k!==name));
  tabButtons.forEach(b=>b.classList.toggle('active',b.dataset.tab===name));
  window.scrollTo({top:0,behavior:'auto'});
}
tabButtons.forEach(b=>b.onclick=()=>openTab(b.dataset.tab));

// Use the exact same visible geometry as the validated quiz map.
const studyMapg=$('#studyMapg');
$$('#mapg path').forEach(p=>{
  const c=p.cloneNode(false);
  c.removeAttribute('class');
  c.id='study_'+p.dataset.id;
  c.dataset.id=p.dataset.id;
  studyMapg.appendChild(c);
});

function renderStudyNotes(region){
  const panel=$('#studyNotesPanel'),box=$('#studyNotesContent'),n=ATLAS_NOTES[region.id]||{};
  let parts=[];
  const tags=[];
  // Show every applicable urban classification together, independent of the map-study submode.
  for(const key of ['first','second','innovation','company','donong','fez']){
    const cfg=CITY_STUDY[key], labels=cfg.items[region.id]||[];
    if(labels.length)tags.push([cfg.label,labels.map(esc).join('<br>')]);
  }
  if(n.core?.length)tags.push(['핵심 개념',n.core.map(esc).join('<br>')]);
  if(n.festival)tags.push(['지역 축제',n.festival]);
  if(n.gi)tags.push(['지리적 표시제',n.gi]);
  if(n.heritage)tags.push(['세계문화유산',n.heritage]);
  if(n.naturalHeritage)tags.push(['세계자연유산',n.naturalHeritage]);
  if(n.ramsar)tags.push(['람사르협약 등재 습지',n.ramsar]);
  if(tags.length)parts.push(`<div class="study-note-tags">${tags.map(([a,b])=>`<div class="study-note-row"><span class="study-note-label">${esc(a)}</span><span class="study-note-value">${(a==='핵심 개념'||Object.values(CITY_STUDY).some(c=>c.label===a))?b:esc(b)}</span></div>`).join('')}</div>`);
  if(parts.length){box.innerHTML=parts.join('');panel.classList.remove('hidden')}else{box.innerHTML='';panel.classList.remove('hidden')}
  const edit=document.createElement('button');edit.type='button';edit.id='kgStudyEdit';edit.className='kg-study-edit';edit.textContent='핵심개념 편집 · 기록';edit.onclick=()=>window.KGCore?.openStudy(region.id);box.appendChild(edit);
  if(document.getElementById('kgCoreCard')?.parentElement===panel){window.KGCore?.selectRegion(region.id);} 
}


