let studyMode='general',memoryMode=false;
function hasStudyType(n,mode,id){if(mode==='festival')return !!n.festival;if(mode==='gi')return !!n.gi;if(mode==='heritage')return !!(n.heritage||n.naturalHeritage||n.ramsar);if(mode==='city')return !!cityStudyItems()[id];return true}
function paintStudyMap(){
 const overlay=$('#studyOverlayg');overlay.innerHTML='';
 $$('#studyMapg path').forEach(p=>{const n=ATLAS_NOTES[p.dataset.id]||{};p.classList.remove('study-dim','study-theme','study-cultural','study-natural','study-selected','study-city-first','study-city-second','study-city-innovation','study-city-company','study-city-donong','study-city-fez');
   if(studyMode==='general')return;
   if(!hasStudyType(n,studyMode,p.dataset.id)){p.classList.add('study-dim');return}
   if(studyMode==='festival'||studyMode==='gi')p.classList.add('study-theme');
   else if(studyMode==='city')p.classList.add(CITY_STUDY[cityStudyMode].cls);
   else if(studyMode==='heritage'){
     if(n.heritage)p.classList.add('study-cultural');
     if(n.naturalHeritage)p.classList.add('study-natural');
     if(n.ramsar){const o=p.cloneNode(false);o.removeAttribute('id');o.removeAttribute('class');o.dataset.id=p.dataset.id;overlay.appendChild(o)}
   }
 });
 if(selectedStudy)$('#study_'+selectedStudy.id)?.classList.add('study-selected');
}
function applyMemory(region){
 const name=$('#studyName'),prov=$('#studyProvince'),notes=$('#studyNotesPanel');
 name.classList.toggle('memory-hidden',memoryMode);prov.classList.toggle('memory-hidden',memoryMode);notes.classList.toggle('memory-hidden',memoryMode);
 let old=$('#memoryReveal');if(old)old.remove();
 if(memoryMode&&region){let b=document.createElement('button');b.id='memoryReveal';b.className='memory-reveal';b.textContent='정답 보기';b.onclick=()=>{name.classList.remove('memory-hidden');prov.classList.remove('memory-hidden');notes.classList.remove('memory-hidden');b.remove()};notes.insertAdjacentElement('afterend',b)}
}
function setStudyMode(mode){studyMode=mode;selectedStudy=null;$$('#studyModes button').forEach(b=>b.classList.toggle('active',b.dataset.smode===mode));$('#heritageLegend').style.display=mode==='heritage'?'flex':'none';$('#citySubModes').style.display=mode==='city'?'flex':'none';$('#cityLegend').style.display=mode==='city'?'flex':'none';const msg={general:'모든 지역을 자유롭게 눌러 학습합니다.',festival:'지역 축제가 입력된 지역만 색칠했습니다.',gi:'지리적 표시제가 입력된 지역만 색칠했습니다.',heritage:'세계문화유산·세계자연유산은 면 색으로, 람사르 습지는 줄무늬로 겹쳐 표시합니다.',city:`${CITY_STUDY[cityStudyMode].label}가 있는 지역을 색칠했습니다.`};$('#studyModeNote').textContent=msg[mode];$('#studyName').textContent='지도를 눌러보세요';$('#studyProvince').textContent='';$('#studyNotesPanel').classList.add('hidden');paintStudyMap()}
$$('#studyModes button').forEach(b=>b.onclick=()=>setStudyMode(b.dataset.smode));
$$('#citySubModes button').forEach(b=>b.onclick=()=>{cityStudyMode=b.dataset.citymode;$$('#citySubModes button').forEach(x=>x.classList.toggle('active',x===b));const cfg=CITY_STUDY[cityStudyMode];$('#cityLegendLabel').textContent=cfg.label;$('#cityLegendSwatch').className='legend-swatch sw-city-'+cityStudyMode;$('#studyModeNote').textContent=cfg.label+'가 있는 지역을 색칠했습니다.';selectedStudy=null;$('#studyName').textContent='지도를 눌러보세요';$('#studyProvince').textContent='';$('#studyNotesPanel').classList.add('hidden');paintStudyMap()});
$('#memoryToggle').onclick=()=>{memoryMode=!memoryMode;$('#memoryToggle').classList.toggle('active',memoryMode);$('#memoryToggle').textContent=memoryMode?'이름 가리기 ON':'이름 가리기';if(selectedStudy)applyMemory(selectedStudy)};
function selectStudyRegion(region){
  const n=ATLAS_NOTES[region.id]||{};if(studyMode!=='general'&&!hasStudyType(n,studyMode,region.id))return;
  selectedStudy=region;
  $$('#studyMapg path').forEach(p=>p.classList.remove('study-selected'));
  const p=$('#study_'+region.id);
  if(p)p.classList.add('study-selected');
  $('#studyName').textContent=region.display;
  $('#studyProvince').textContent=region.province;
  renderStudyNotes(region);renderPopulation(region);renderClimate(region);renderStudyIndustry(region);applyMemory(region);
  window.dispatchEvent(new CustomEvent('pop-history-study-select',{detail:{region}}));
}

function studyHit(ev){
  let q=svgPoint(ev),dot=$('#studyTouchdot');
  dot.setAttribute('cx',q.x);dot.setAttribute('cy',q.y);
  clearTimeout(window.studyDotTimer);
  window.studyDotTimer=setTimeout(()=>{dot.setAttribute('cx',-50);dot.setAttribute('cy',-50)},900);
  let hits=BANK.filter(b=>regionHas(b.id,q.x,q.y)),clicked=null;
  if(hits.length===1)clicked=hits[0];
  else if(hits.length>1){
    const eps=1.2, offsets=[[0,0],[eps,0],[-eps,0],[0,eps],[0,-eps],[eps,eps],[-eps,eps],[eps,-eps],[-eps,-eps]];
    let best=-1;
    hits.forEach(h=>{let sc=offsets.reduce((a,o)=>a+(regionHas(h.id,q.x+o[0],q.y+o[1])?1:0),0);if(sc>best){best=sc;clicked=h}});
  }
  if(clicked)selectStudyRegion(clicked);
}
bindTap($('#studySvg'),studyHit);


